    const total = Number(this.metricasSatisfaccionGeneralData?.total_respuestas ?? 0);
    if (!hasBottom1 && !(Number.isFinite(total) && total > 0))
      return this.COLOR_GRAY;
    return this.colorByPct(this.getBottom1GaugeValue(), true);
